mapper.sql:
FROM product_statistics ps

    INNER JOIN product_spu spu
        ON spu.id = ps.spu_id
       AND spu.tenant_id = ps.tenant_id
       AND spu.deleted = FALSE

WHERE ps.tenant_id = #{tenantId}
  AND ps.deleted = FALSE
  AND ps.time BETWEEN #{startDate} AND #{endDate}

  AND spu.category_id = #{categoryId}


  AND ps.spu_id = #{spuId}

mapper.select:
SELECT aggregated.*
FROM () aggregated




LIMIT #{limit} OFFSET #{offset}
